evaluates SPARQL expression SELECT $this ?path
WHERE {
  OPTIONAL { $this <https://axiolune.ai/ontology/finance/market-structure/otcCounterpartyA> ?counterpartyA . }
  OPTIONAL { $this <https://axiolune.ai/ontology/finance/market-structure/otcCounterpartyB> ?counterpartyB . }
  BIND(<https://axiolune.ai/ontology/finance/market-structure/otcCounterpartyA> AS ?path)
  FILTER (
    (BOUND(?counterpartyA) && !BOUND(?counterpartyB))
    || (!BOUND(?counterpartyA) && BOUND(?counterpartyB))
    || (BOUND(?counterpartyA) && BOUND(?counterpartyB)
        && STR(?counterpartyA) >= STR(?counterpartyB))
  )
}
